using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class DestructionWorkflowOperations:RefCounted
{
    private static Resource? ResourceValue(Variant value)=>value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;
    private readonly DestructionAuthoringOperations _authoring=new();private readonly DestructionDefinitionOperations _definition=new();private readonly PhysicsSettingsOperations _settings=new();private readonly ActorDataOperations _data=new();private readonly ActorAnimationOperations _animation=new();
    private static Control Host(Control owner)=>owner.Get("host").As<Control>();private static Resource Actor(Control owner)=>owner.Get("actor").As<Resource>();private static RefCounted Model(Control owner)=>Host(owner).Get("model").As<RefCounted>();private static Label Status(Control owner)=>owner.Get("status").As<Label>();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private Resource? Setup(Control owner){var value=ResourceValue(Get(Actor(owner).Get("values").AsGodotDictionary(),"destruction_setup"));return ActorDataOperations.ScriptIs(value,"res://scripts/actors/core/actor_object_reference.gd")?_animation.resolve_reference(value!):null;}
    private static Button ActionButton(Node parent,string title,Action action){var button=new Button{Text=title,Name=title.ValidateNodeName()};parent.AddChild(button);button.Pressed+=action;return button;}
    public Button button(Control owner,Node parent,string title,Variant callback){var button=new Button{Text=title,Name=title.ValidateNodeName()};parent.AddChild(button);owner.Call("_connect_button",button,callback);return button;}
    public Control? editor(Control owner){foreach(var node in owner.GetTree().GetNodesInGroup("actor_timeline_editors"))if(node.Get("model").AsGodotObject()==Model(owner))return node as Control;return null;}
    public void setup(VBoxContainer owner,Control inspector,Resource actor,bool actions){owner.Set("host",inspector);owner.Set("actor",actor);owner.Set("workflow",actions);var status=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart};status.AddThemeFontSizeOverride("font_size",12);owner.Set("status",status);if(actions){var flow=new HFlowContainer();owner.AddChild(flow);foreach(string value in new[]{"Preview","Recalculate","Freeze","Bake group…","Clear bake","Reset to original"}){string title=value;ActionButton(flow,title,()=>run(owner,title));}var assets=new HBoxContainer();owner.AddChild(assets);ActionButton(assets,"Capture setup",()=>capture(owner));ActionButton(assets,"Apply setup",()=>apply_setup(owner));var baked=new HFlowContainer();owner.AddChild(baked);ActionButton(baked,"Capture baked assembly",()=>capture_baked(owner));ActionButton(baked,"Instantiate baked assembly",()=>instantiate_baked(owner));}else{var row=new HBoxContainer();owner.AddChild(row);ActionButton(row,"Direct fragments…",()=>owner.Call("open_fragments"));var viewport=new CheckButton{Name="DirectFragmentsViewport",Text="Pick",TooltipText="Pick fragments in the viewport; Shift-click adds to the group. Drag the target handle to guide them.",ButtonPressed=actor.GetMeta("damage_fragment_tool",false).AsBool()};row.AddChild(viewport);viewport.Toggled+=value=>{actor.SetMeta("damage_fragment_tool",value);actor.SetMeta("damage_viewport_tool",value);};}owner.AddChild(status);}
    public void capture(Control owner){var view=editor(owner);if(view==null)return;var setup=_authoring.capture_setup(view.Get("physics").As<RefCounted>(),Actor(owner));_authoring.edit(Model(owner),Actor(owner),new StringName("destruction_setup"),_data.from_object(setup),"Capture reusable destruction setup");Status(owner).Text="Setup captured. Expand Reusable setup to save it to the project or copy it.";Host(owner).Call("_queue_rebuild_selected");}
    public void apply_setup(Control owner){var view=editor(owner);if(view!=null)Status(owner).Text=_authoring.apply_setup(Model(owner),view.Get("physics").As<RefCounted>(),Actor(owner),Setup(owner));}
    public void capture_baked(Control owner){var view=editor(owner);if(view==null)return;var result=GD.Load<GDScript>("res://scripts/actors/physics/destruction/bake_editing.gd").Call("portable_scene",view).AsGodotDictionary();if(result["error"].AsString().Length>0){Status(owner).Text=result["error"].AsString();return;}var setup=_authoring.capture_setup(view.Get("physics").As<RefCounted>(),Actor(owner));setup.Get("values").AsGodotDictionary()[new StringName("baked_assembly")]=result["scene"];_authoring.edit(Model(owner),Actor(owner),new StringName("destruction_setup"),_data.from_object(setup),"Capture reusable baked assembly");Status(owner).Text="Baked interacting rigid assembly captured. Save Reusable setup to reuse it. New contacts require recalculation.";Host(owner).Call("_queue_rebuild_selected");}
    public void instantiate_baked(Control owner){var setup=Setup(owner);var view=editor(owner);var assembly=setup!=null?ResourceValue(Get(setup.Get("values").AsGodotDictionary(),"baked_assembly")):null;if(view==null||assembly==null){Status(owner).Text="Load a setup containing a baked assembly first.";return;}var model=Model(owner);var clip=model.Call("instantiate_scene",assembly,Host(owner).Get("registry").AsGodotObject().Call("get_definition",new StringName("point_3d")),view.Get("canvas").AsGodotObject().Get("playhead"),model.Get("selected_layer"),Get(setup!.Get("values").AsGodotDictionary(),"name","Baked assembly"),"Instantiate baked rigid assembly");Status(owner).Text=clip.AsGodotObject()!=null?"Baked assembly inserted. Move its parent to place it; new physical contacts require recalculation.":"Could not instantiate the baked assembly.";}
    public void run(Control owner,string title){var view=editor(owner);if(view==null)return;var actor=Actor(owner);var physics=view.Get("physics").AsGodotObject();var model=Model(owner);switch(title){case "Preview":actor.SetMeta("damage_pattern_preview",false);view.Set("playing",!view.Get("playing").AsBool());break;case "Freeze":physics.Call("freeze",model,actor);break;case "Bake group…":owner.Call("bake_dialog",view);break;case "Clear bake":var before=_settings.authored(actor);var after=before.Duplicate(true);after["mode"]=Get(before["bake"].AsGodotDictionary(),"source_mode",1).AsInt32();after["bake"]=new Settings();var history=model.Get("history").As<UndoRedo>();var action=new PhysicsSettingsHistoryAction(model,actor,before,after);history.CreateAction("Clear physics bake");history.AddDoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_before)));history.AddDoReference(action);history.CommitAction();break;case "Reset to original":var operations=Get(actor.Get("values").AsGodotDictionary(),"destruction_operations",new Settings()).AsGodotDictionary().Duplicate(true);foreach(var value in operations.Values)value.AsGodotDictionary()["enabled"]=false;_definition.edit(model,actor,operations,"Disable destruction stack");Status(owner).Text="Operations disabled; source preserved. Re-enable an operation to restore its setup.";break;case "Recalculate":var settings=_settings.authored(actor);if(settings["mode"].AsInt32() is 3 or 4)_settings.edit(model,actor,"mode",Get(settings["bake"].AsGodotDictionary(),"source_mode",1).AsInt32());physics.Set("signature","");physics.Call("mark_dirty");view.Call("_evaluate_runtimes");Status(owner).Text="Simulation reset. Unchanged prepared fracture geometry is reused.";break;}}
}
